    authors: { font_size: 12, font_color: '000000' }
  # Code indented 17 pt, nothing around it.
  code:
    padding: [0, 0, 0, 17]
  # An uppercase label between 0.5 pt rules.
  admonition:
    padding: [6, 0, 6, 0]
    border_width: [0.5, 0, 0.5, 0]
    border_color: '000000'
    column_rule_width: 0
    label:
      text_transform: uppercase
      font_size: 9
      vertical_align: top
      padding: [1.5, 12, 0, 0]
  # The running foot: the page number outside, then the chapter (verso)
  # or section (recto). No head.
  header:
    recto: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
    verso: { left: { content: '' }, center: { content: '' }, right: { content: '' } }
